head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst10400";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — isExaService

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst10400.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_54", fn: function(){ return ((dma_pageContext.get("isExaService") ?? "") === 'Y'); } }, { id: "c_otherwise_69", fn: function(){ return (!(((dma_pageContext.get("isExaService") ?? "") === 'Y'))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        $c.util.getComponent("tabContents").setStyle("display", "none");
        /* TODO Stage2: [sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
        await scwin.initComNmSetting();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst10400.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name searchForm_onsubmit
 * @description searchForm onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.searchForm_onsubmit = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst10400.searchForm_onsubmit' }); }
};

/**
 * @method
 * @name btn_fnCommFindCorpName_onclick
 * @description btn_fnCommFindCorpName 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_fnCommFindCorpName_onclick = function(e){
    try {
        scwin.fnCommFindCorpName(); return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst10400.btn_fnCommFindCorpName_onclick' }); }
};

/**
 * @method
 * @name btn_fnSearchCorpName_onclick
 * @description btn_fnSearchCorpName 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnSearchCorpName_onclick = async function(e){
    try {
        await scwin.fnSearchCorpName(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst10400.btn_fnSearchCorpName_onclick' }); }
};

/**
 * @method
 * @name tabView_onclick
 * @description tabView 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tabView_onclick = async function(e){
    try {
        await scwin.fnTabView(0)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst10400.tabView_onclick' }); }
};

/**
 * @method
 * @name tabView_2_onclick
 * @description tabView_2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tabView_2_onclick = async function(e){
    try {
        await scwin.fnTabView(1)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst10400.tabView_2_onclick' }); }
};

/**
 * @method
 * @name tabView_3_onclick
 * @description tabView_3 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tabView_3_onclick = async function(e){
    try {
        await scwin.fnTabView(2)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst10400.tabView_3_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnSearchPresentPrice_ajaxsubmit
 * @description fn Search Present Price ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearchPresentPrice_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearchPresentPrice_ajaxsubmit",
        method: "post",
        action: "/corpdetail/chart.do",
        ref: "dma_fnSearchPresentPriceAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnSearchDisclsChartInfo_ajaxsubmit
 * @description fn Search Discls Chart Info ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearchDisclsChartInfo_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearchDisclsChartInfo_ajaxsubmit",
        method: "post",
        action: "/corpdetail/chart.do",
        ref: "dma_fnSearchDisclsChartInfoAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initComNmSetting
 * @description init Com Nm Setting 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initComNmSetting = async function () {
    const comnm = scwin.getRecentCompanyFromCookie();
    if (comnm !== null && comnm !== "") {
        $c.util.getComponent('ipt_comAbbrv').setValue(comnm);
        await scwin.fnSearchCorpName();
    } else {
        /* TODO Stage2: [sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
    }
};

/**
 * @method
 * @name keyEvent
 * @description key Event 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.keyEvent = async function (e) {
    if ($c.util.getKeyCode(typeof e !== 'undefined' && e ? e : (typeof event !== 'undefined' ? event : undefined)) === 13 || (typeof e !== 'undefined' && e === 13)) {
        if ($c.util.getKeyCode(event) === 13) {
            if (fnAKCKwdSearchCodeType(((document.searchForm || { elements: [] }).comAbbrv))) {
                await scwin.fnSearchCorpName();
            }
        }
    }
};

/**
 * @method
 * @name fnTabView
 * @description fn Tab View 처리
 * @param {Number} idx idx
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnTabView = async function (idx) {
    $(document).find("li[id=tabView]").each(function(index) {
            if (idx === index) {
                if (!$(this).hasClass("active")) {
                    $(this).addClass("active");
                }
            } else {
                if ($(this).hasClass("active")) {
                    $(this).removeClass("active");
                }
            }
    });
    if (idx === "0") {
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("method", "loadPageForDisclsAnalysisChart");
    } else {
        if (idx === "1") {
            $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("method", "loadPageForIdxComparisonChart");
        } else {
            if (idx === "2") {
                $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("method", "loadPageForIssueComparisonChart");
            }
        }
    }
    await scwin.fnSearchDisclsChartInfo();
};

/**
 * @method
 * @name getRecentCompanyFromCookie
 * @description get Recent Company From Cookie 처리
 * @returns {void}
 * @hidden N
 */
scwin.getRecentCompanyFromCookie = function () {
    const cookies = scwin.fnGetCookie('krxComp');
    const item = null;
    let userCompaniesArray = null;
    let tmpstr = null;
    if (cookies !== null) {
        userCompaniesArray = cookies.split("/");
    }
    const issues = "";
    tmpstr = "";
    if (userCompaniesArray !== null && userCompaniesArray !== "") {
        tmpstr = userCompaniesArray[0].split(",");
    }
    return tmpstr[2];
};

/**
 * @method
 * @name fnGetCookie
 * @description fn Get Cookie 처리
 * @param {*} keyname keyname
 * @returns {void}
 * @hidden N
 */
scwin.fnGetCookie = function (keyname) { const v = $c.util.getSessionStorage(keyname); return (v === undefined || v === null) ? '' : v; };

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    let comAbbrv = $c.util.getComponent('ipt_comAbbrv').getValue(); if (comAbbrv === null) { comAbbrv = ''; }
    if (comAbbrv === null || comAbbrv === "") {
        await $c.win.alert("회사명을 입력해 주세요.");
        return;
    }
    $c.util.getComponent("tabContents").setStyle("display", "");
    /* TODO Stage2: [sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
    await scwin.fnSearchPresentPrice();
    await scwin.fnSearchDisclsChartInfo();
    scwin.closeSearchAutoCompleteDiv();
};

/**
 * @method
 * @name fnSearchPresentPrice
 * @description fn Search Present Price 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchPresentPrice = async function () {
    await scwin.tx_fnSearchPresentPrice_ajaxsubmit();
};

/**
 * @method
 * @name fnSearchPresentPriceCallBack
 * @description fn Search Present Price Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchPresentPriceCallBack = function (data) {
    $("#mainContentsPrice").empty().append(data);
};

/**
 * @method
 * @name fnSearchDisclsChartInfo
 * @description fn Search Discls Chart Info 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchDisclsChartInfo = async function () {
    await scwin.tx_fnSearchDisclsChartInfo_ajaxsubmit();
};

/**
 * @method
 * @name fnSearchViewCallBack
 * @description fn Search View Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchViewCallBack = function (data) {
    $("#mainContentsView").empty().append(data);
};

/**
 * @method
 * @name fnSearchCorpName
 * @description fn Search Corp Name 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpName = async function () {
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isurCd", "");
    let val = $c.util.getComponent('ipt_comAbbrv').getValue(); if (val === null) { val = ''; }
    if (val !== "") {
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("searchCorpName", val);
        /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnAKCKwdSearchCorpName( " ') */
    } else {
        await scwin.fnSearch();
    }
};

/**
 * @method
 * @name fnSearchCorpNameAllCallBack
 * @description fn Search Corp Name All Call Back 처리
 * @param {*} items items
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpNameAllCallBack = async function (items) {
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isurCd", "");
    if (items.length === 1) {
        await scwin.fnSearchCorpCode(items[0]);
    } else {
        if (items.length > 1) {
            scwin.fnCommFindCorpName();
        } else {
            await scwin.fnSearchCorpCode(null);
        }
    }
};

/**
 * @method
 * @name fnSearchCorpCode
 * @description fn Search Corp Code 처리
 * @param {*} items items
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpCode = async function (items) {
    if (items === null) {
        const val = ($c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").get("searchCodeType") || '');
        if (val === "number") {
            await $c.win.alert("조회한 종목코드가 존재하지 않습니다.");
        } else {
            await $c.win.alert("조회한 회사명이 존재하지 않습니다.");
        }
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isurCd", '');
        $c.util.getComponent('ipt_comAbbrv').setValue('');
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
    } else {
        const comabbr = $c.util.getComponent('ipt_comAbbrv');
        const isurcd = items.isurcd;
        const repisucd = $c.util.getComponent('ipt_repIsuCd');
        const repisusrtkornm = items.repisusrtkornm;
        const spotisutrdmkttpcd = items.spotisutrdmkttpcd;
        const liststatcd = items.liststatcd;
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("comAbbrv", comabbr);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isurCd", isurcd);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isucd", repisucd);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isunm", repisusrtkornm);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("comAbbrv", comabbr);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isurCd", isurcd);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isucd", repisucd);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isunm", repisusrtkornm);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("marketType", spotisutrdmkttpcd);
        if (spotisutrdmkttpcd === "1") {
            $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("market", "stock");
        } else {
            if (spotisutrdmkttpcd === "2") {
                $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("market", "kosdaq");
            } else {
                if (spotisutrdmkttpcd === "6") {
                    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("market", "konex");
                }
            }
        }
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isurCd", isurcd);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("marketType", spotisutrdmkttpcd);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("repIsuCd", repisucd);
        $c.util.getComponent('ipt_comAbbrv').setValue(comabbr);
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("liststatcd", liststatcd);
        await scwin.fnSearch();
    }
};

/**
 * @method
 * @name fnCommFindCorpName
 * @description fn Comm Find Corp Name 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnCommFindCorpName = function () {
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("searchCorpMode", "");
    /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnFindCorpName2( " ') */
};

/**
 * @method
 * @name setCorpInfo2
 * @description set Corp Info2 처리
 * @param {*} isurcd isurcd
 * @param {String} kisComCd kisComCd
 * @param {*} repisucd repisucd
 * @param {*} repisukornm repisukornm
 * @param {String} repIsuSrtCd repIsuSrtCd
 * @param {String} comNm comNm
 * @param {*} comAbbrv comAbbrv
 * @param {*} isurSymbl isurSymbl
 * @param {*} fssUnqNo fssUnqNo
 * @param {*} ipt_markettype ipt_markettype
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo2 = function (isurcd, kisComCd, repisucd, repisukornm, repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo, ipt_markettype) {
    if (($c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").get("searchCorpMode") || '') === 'Y') {
        setAddCorpInfo(isurcd, kisComCd, repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo);
        return;
    }
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("comAbbrv", comAbbrv);
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isurCd", isurcd);
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isucd", repisucd);
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isunm", repisukornm);
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("comAbbrv", comAbbrv);
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isurCd", isurcd);
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isucd", repisucd);
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isunm", repisukornm);
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("marketType", ipt_markettype);
    if (ipt_markettype === "1") {
        $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("market", "stock");
    } else {
        if (ipt_markettype === "2") {
            $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("market", "kosdaq");
        } else {
            if (ipt_markettype === "6") {
                $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("market", "konex");
            }
        }
    }
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("isurCd", isurcd);
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("marketType", ipt_markettype);
    $c.util.getComponent("dma_fnSearchPresentPriceAjaxsubmitReq").set("repIsuCd", repisucd);
    $c.util.getComponent('ipt_comAbbrv').setValue(comAbbrv);
};

/**
 * @method
 * @name closeSearchAutoCompleteDiv
 * @description close Search Auto Complete Div 처리
 * @returns {void}
 * @hidden N
 */
scwin.closeSearchAutoCompleteDiv = function () {
    const AKC_Div = $c.util.getComponent("AKCDiv");
    if (AKC_Div !== null) {
        if (AKC_Div.style.display !== "none") {
            (!AKC_Div ? console.warn('[sdd] 표시 전환 대상 미해결: AKC_Div') : (("none") === 'none' ? (AKC_Div.hide ? AKC_Div.hide() : void 0) : (AKC_Div.show ? AKC_Div.show() : void 0)));
        }
    }
};
